import { GenericColumn, StringColumn, Table } from '../../db'

export const sys_auth_profile_basic = Table({
    name: 'sys_auth_profile_basic',
    extends: 'sys_auth_profile',
    schema: {
        password: GenericColumn({
            mandatory: false,
            label: 'Password',
            read_only: false,
            active: true,
            column_type: 'password2',
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        username: StringColumn({
            mandatory: true,
            label: 'Username',
            read_only: false,
            active: true,
            maxLength: 80,
            dropdown: 'none',
        }),
    },
})
